<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><?=view('components/page_header',['eyebrow'=>'Tours / Departures','title'=>esc($tour['name']),'subtitle'=>'Manage departure dates and capacity.'])?><div class="card form-card"><form method="post" action="<?=site_url('tours/departures/store/'.$tour['id'])?>"><?=csrf_field()?><div class="form-grid"><div class="form-group"><label>Departure Date *</label><input type="date" name="departure_date" required></div><div class="form-group"><label>Return Date *</label><input type="date" name="return_date" required></div><div class="form-group"><label>Capacity *</label><input type="number" name="capacity" min="1" required value="20"></div><div class="form-group"><label>Status</label><select name="status"><option value="draft">Draft</option><option value="open" selected>Open</option><option value="full">Full</option><option value="cancelled">Cancelled</option></select></div><div class="form-group full"><label>Meeting Point</label><input name="meeting_point"></div><div class="form-group full"><label>Notes</label><textarea name="notes" rows="2"></textarea></div></div><div class="form-actions"><a class="btn btn-secondary" href="<?=site_url('tours')?>">Back</a><button class="btn btn-primary">Add Departure</button></div></form></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Departure</th><th>Return</th><th>Capacity</th><th>Status</th><th>Meeting Point</th><th>Action</th></tr></thead><tbody><?php foreach($departures as $d): ?><tr><td><?=esc($d['departure_date'])?></td><td><?=esc($d['return_date'])?></td><td><?=esc($d['capacity'])?></td><td><?=view('components/status_badge',['status'=>$d['status']])?></td><td><?=esc($d['meeting_point']?:'-')?></td><td><?php if($d['status']!=='cancelled'): ?><form method="post" action="<?=site_url('tours/departures/cancel/'.$d['id'])?>" onsubmit="return confirm('Cancel this departure?')" style="display:inline"><?=csrf_field()?><button class="btn btn-danger">Cancel</button></form><?php endif;?></td></tr><?php endforeach; if(empty($departures)): ?><tr><td colspan="6" class="empty-cell">No departures yet.</td></tr><?php endif;?></tbody></table></div></div><?= $this->endSection() ?>